-- Supplier codes for all Parts phone lists. Existing names/privacy and workflow remain unchanged.
begin;
do $$begin if public.get_employee_directory_version()is distinct from '20261026-employees-1'then raise exception 'Verified Shared Employees update is required.';end if;if to_regprocedure('public.get_parts_supplier_codes_version()')is not null then if public.get_parts_supplier_codes_version()is distinct from '20261027-parts-supplier-codes-1'then raise exception 'Existing Parts supplier code support needs review.';end if;end if;end;$$;
create or replace function greenloop_private.psc_returns()returns table(id uuid,order_id uuid,legacy boolean,imei text,model text,storage_gb integer,color text,technician_name text,part_name text,quantity integer,status text,classification text,requested_at timestamptz,reviewed_at timestamptz,review_notes text,supplier_code text)language sql stable security definer set search_path=pg_catalog,public as $$
 select r.*,supplier.supplier_code::text from greenloop_private.pp_returns()r left join greenloop_private.parts_flow_orders o on o.id=r.order_id left join public.lab_part_return_requests lr on r.legacy and lr.id=r.id left join public.jobs j on j.id=coalesce(o.job_id,lr.job_id)left join public.suppliers supplier on supplier.id=j.supplier_id;
$$;
create or replace function public.get_parts_supplier_queue_v1(p_filters jsonb default '{}',p_offset integer default 0,p_limit integer default 50,p_sort_key text default 'submitted_at',p_sort_direction text default 'desc')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare f date;t date;s text;st text;sc text;result jsonb;begin
 perform greenloop_private.pf_cap('parts','view');
 if jsonb_typeof(p_filters)is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_filters)k where k not in ('_search','_from','_to','status','supplier_code'))or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 100 or p_sort_key is null or p_sort_key not in ('submitted_at','imei','model','status','supplier_code')or p_sort_direction is null or p_sort_direction not in ('asc','desc')then raise exception 'Select valid filters and sorting.'using errcode='22023';end if;
 if p_filters<>'{}'then perform greenloop_private.pf_cap('parts','search');end if;if p_sort_key<>'submitted_at' or p_sort_direction<>'desc'then perform greenloop_private.pf_cap('parts','sort');end if;
 f:=nullif(p_filters->>'_from','')::date;t:=nullif(p_filters->>'_to','')::date;s:=lower(btrim(coalesce(p_filters->>'_search','')));st:=nullif(p_filters->>'status','');sc:=nullif(p_filters->>'supplier_code','');if f>t or length(s)>120 or length(sc)>120 then raise exception 'Select valid dates or search.'using errcode='22023';end if;
 with base as materialized(select o.id order_id,o.revision,o.submitted_at,d.imei_1 imei,d.model,d.storage_gb,d.color,j.job_number,supplier.supplier_code,greenloop_private.ps_status(o.id)status,coalesce((select s.assigned_technician_name from public.job_work_order_steps s where s.id=o.step_id),'Unassigned')technician_name,(select count(*)from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and r.status<>'cancelled')parts_count from greenloop_private.parts_flow_orders o join public.jobs j on j.id=o.job_id and j.deleted_at is null join public.devices d on d.id=o.device_id and d.deleted_at is null left join public.suppliers supplier on supplier.id=j.supplier_id where greenloop_private.ps_has_parts(o.id)),q as materialized(select * from base where(f is null or(submitted_at at time zone 'Asia/Dubai')::date>=f)and(t is null or(submitted_at at time zone 'Asia/Dubai')::date<=t)and(s=''or strpos(lower(concat_ws(' ',imei,model,storage_gb,color,job_number,technician_name,supplier_code)),s)>0)and(st is null or status=st)and(sc is null or supplier_code=sc)),page as(select *from q order by case when p_sort_key='submitted_at'and p_sort_direction='asc'then submitted_at end asc,case when p_sort_key='submitted_at'and p_sort_direction='desc'then submitted_at end desc,case when p_sort_direction='asc'then case p_sort_key when 'imei'then imei when 'model'then model when 'status'then status when 'supplier_code'then supplier_code end end asc,case when p_sort_direction='desc'then case p_sort_key when 'imei'then imei when 'model'then model when 'status'then status when 'supplier_code'then supplier_code end end desc,order_id offset p_offset limit p_limit)
 select jsonb_build_object('total',(select count(*)from q),'rows',coalesce((select jsonb_agg(to_jsonb(p))from page p),'[]'),'facets',jsonb_build_object('status',(select coalesce(jsonb_agg(distinct status),'[]')from base),'supplier_code',(select coalesce(jsonb_agg(distinct supplier_code order by supplier_code),'[]')from base where supplier_code is not null)))into result;return result;
end;$$;
create or replace function public.get_parts_supplier_returns_v1(p_filters jsonb default '{}',p_category text default 'pending',p_offset integer default 0,p_limit integer default 50,p_sort_key text default 'requested_at',p_sort_direction text default 'desc')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare f date;t date;s text;sc text;result jsonb;begin
 perform greenloop_private.pf_cap('parts','view');if jsonb_typeof(p_filters)is distinct from 'object'or exists(select 1 from jsonb_object_keys(p_filters)k where k not in ('_search','_from','_to','supplier_code'))or p_category is null or p_category not in ('pending','damaged','faulty','not_needed','other')or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 100 or p_sort_key is null or p_sort_key not in ('requested_at','imei','model','part_name','quantity','supplier_code')or p_sort_direction is null or p_sort_direction not in ('asc','desc')then raise exception 'Select valid return filters.'using errcode='22023';end if;
 if p_filters<>'{}'then perform greenloop_private.pf_cap('parts','search');end if;if p_sort_key<>'requested_at'or p_sort_direction<>'desc'then perform greenloop_private.pf_cap('parts','sort');end if;f:=nullif(p_filters->>'_from','')::date;t:=nullif(p_filters->>'_to','')::date;s:=lower(btrim(coalesce(p_filters->>'_search','')));sc:=nullif(p_filters->>'supplier_code','');if f>t or length(s)>120 or length(sc)>120 then raise exception 'Select valid dates or search.'using errcode='22023';end if;
 with source as materialized(select *from greenloop_private.psc_returns()),base as materialized(select *from source where(sc is null or supplier_code=sc)and(f is null or(requested_at at time zone 'Asia/Dubai')::date>=f)and(t is null or(requested_at at time zone 'Asia/Dubai')::date<=t)and(s=''or strpos(lower(concat_ws(' ',imei,model,storage_gb,color,technician_name,part_name,review_notes,supplier_code)),s)>0)),q as materialized(select *from base where case when p_category='pending'then status='pending'else status='approved'and classification=p_category end),page as(select *from q order by case when p_sort_key='requested_at'and p_sort_direction='asc'then requested_at end asc,case when p_sort_key='requested_at'and p_sort_direction='desc'then requested_at end desc,case when p_sort_key='quantity'and p_sort_direction='asc'then quantity end asc,case when p_sort_key='quantity'and p_sort_direction='desc'then quantity end desc,case when p_sort_direction='asc'then case p_sort_key when 'imei'then imei when 'model'then model when 'part_name'then part_name when 'supplier_code'then supplier_code end end asc,case when p_sort_direction='desc'then case p_sort_key when 'imei'then imei when 'model'then model when 'part_name'then part_name when 'supplier_code'then supplier_code end end desc,id offset p_offset limit p_limit)
 select jsonb_build_object('total',(select count(*)from q),'rows',coalesce((select jsonb_agg(to_jsonb(p))from page p),'[]'),'counts',(select jsonb_build_object('pending',count(*)filter(where status='pending'),'damaged',coalesce(sum(quantity)filter(where status='approved'and classification='damaged'),0),'faulty',coalesce(sum(quantity)filter(where status='approved'and classification='faulty'),0),'not_needed',coalesce(sum(quantity)filter(where status='approved'and classification='not_needed'),0),'other',coalesce(sum(quantity)filter(where status='approved'and classification='other'),0))from base),'facets',jsonb_build_object('supplier_code',(select coalesce(jsonb_agg(distinct supplier_code order by supplier_code),'[]')from source where supplier_code is not null)))into result;return result;
end;$$;
create or replace function public.get_parts_supplier_order_v1(p_order_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare result jsonb;code text;begin
 perform greenloop_private.pf_cap('parts','view');result:=public.get_parts_flow_order_v1(p_order_id);select supplier.supplier_code into code from greenloop_private.parts_flow_orders o join public.jobs j on j.id=o.job_id left join public.suppliers supplier on supplier.id=j.supplier_id where o.id=p_order_id;return jsonb_set(result,'{device}',(result->'device')||jsonb_build_object('supplier_code',code));
end;$$;
insert into greenloop_private.capability_rpc_rules values('get_parts_supplier_queue_v1','{"page":"parts","capability":"view","read":true}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_parts_supplier_returns_v1','{"page":"parts","capability":"view","read":true}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_parts_supplier_order_v1','{"page":"parts","capability":"view","read":true}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r)where identity='rules';
do $wrap$declare f record;impl text;impl_identity text;args text;body text;begin
 for f in select p.*,pg_get_functiondef(p.oid)ddl,p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('get_parts_supplier_queue_v1','get_parts_supplier_returns_v1','get_parts_supplier_order_v1')loop
 impl:='office_impl_'||f.oid;execute regexp_replace(f.ddl,'FUNCTION public\.'||f.proname||'\(','FUNCTION greenloop_private.'||impl||'(');impl_identity:='greenloop_private.'||impl||'('||oidvectortypes(f.proargtypes)||')';execute format('revoke all on function %s from public,anon,authenticated',impl_identity);select coalesce(string_agg('$'||i,','order by i),'')into args from generate_series(1,f.pronargs)i;
 body:=E'begin\n -- greenloop-office-wrapper-196\n perform greenloop_private.require_office_network();\n return greenloop_private.'||impl||'('||args||E');\nend;';execute format('create or replace function public.%I(%s)returns %s language plpgsql %s security definer set search_path=pg_catalog,public as %L',f.proname,pg_get_function_arguments(f.oid),pg_get_function_result(f.oid),case f.provolatile when 's'then 'stable'else 'volatile'end,body);execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to authenticated',f.signature);insert into greenloop_private.office_routines values(f.signature,impl_identity,md5(pg_get_functiondef(impl_identity::regprocedure)),md5(pg_get_functiondef(f.oid)))on conflict(identity)do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
 end loop;for f in select p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='greenloop_private'::regnamespace and p.proname='psc_returns'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);end loop;
end;$wrap$;
create table if not exists greenloop_private.parts_supplier_installation(identity text primary key,hash text not null);
alter table greenloop_private.parts_supplier_installation enable row level security;revoke all on greenloop_private.parts_supplier_installation from public,anon,authenticated;
insert into greenloop_private.parts_supplier_installation select p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid))from pg_proc p where(p.pronamespace='public'::regnamespace and p.proname in ('get_parts_supplier_queue_v1','get_parts_supplier_returns_v1','get_parts_supplier_order_v1'))or(p.pronamespace='greenloop_private'::regnamespace and p.proname='psc_returns')on conflict(identity)do update set hash=excluded.hash;
create or replace function public.get_parts_supplier_codes_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_employee_directory_version()='20261026-employees-1'
 and(select count(*)=4 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.parts_supplier_installation)
 and not has_table_privilege('authenticated','greenloop_private.parts_supplier_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')and not has_table_privilege('anon','greenloop_private.parts_supplier_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')
 and not has_function_privilege('authenticated','greenloop_private.psc_returns()','EXECUTE')and not has_function_privilege('anon','greenloop_private.psc_returns()','EXECUTE')
 then '20261027-parts-supplier-codes-1'end;$$;
revoke all on function public.get_parts_supplier_codes_version()from public;grant execute on function public.get_parts_supplier_codes_version()to anon,authenticated;
do $$begin if public.get_parts_supplier_codes_version()is distinct from '20261027-parts-supplier-codes-1'then raise exception 'Parts supplier codes verification failed.';end if;end;$$;
notify pgrst,'reload schema';commit;
select public.get_parts_supplier_codes_version()as installed_parts_supplier_codes_version;
